          'المغسل الرخامي الطبيعي قطعة منفصلة عن سطح العمل. يُنحت من كتلة حجر واحدة ويُحفر فيها فتحة الصرف والمجرى. شكله الحر يجعلها نقطة جذب في أي حمام أو زاوية ضيافة. القطعة الواحدة تعطي إحساساً بالبرودة والمتانة لا تجده في الخزف أو الكوريان.',
          'الميزة الحقيقية للرخام أنه يتصلح. الخدوش السطحية تزال بالجلي السطحي وإعادة التلميع. البقع الحديثة غالباً تُنظف بمعجلة خفيفة وإسفنجة ناعمة. هذه القابلية على الإصلاح تمد عمر المغسل سنوات طويلة. الجرانيت يقاوم الخدش أفضل لكنه أقل مرونة في التلميع الموضعي.',
          'الرخام المهندس خيار شائع أيضاً. هو متجانس اللون ويقاوم البقع أكثر من الطبيعي. لكنه لا يتحمل الحرارة العالية ولا يصلح قرب مصدر حرارة مباشر. الرخام الطبيعي والجرانيت يبقيان الخيار الأول لعشاق الحجر الحقيقي. القرار بينهما يعتمد على طريقة الاستخدام ووقت الصيانة المتاح.',
