          'الرخام حجر طبيعي تكوّن من كربونات الكالسيوم تحت تأثير الحرارة والضغط خلال ملايين السنين، وعروقه المتشعبة لا تتكرر في قطعتين، ولهذا تبقى كل مغسلة رخام قطعة فريدة تحمل بصمة حجرية خاصة. في المدينة المنورة يتزايد إقبال أصحاب الفلل والشقق المفروشة على مغاسي الرخام لأنها تجمع بين الأناقة الكلاسيكية والبرودة الطبيعية التي تريح اليد. كما أن توفر الرخام بدرجات وأسعار متعددة يجعله خياراً يناسب مختلف الميزانيات.',
          'من الناحية الفنية تتراوح صلابة الرخام بين 3 و5 درجات على مقياس موهس، وكثافته تقارب 2.7 جرام لكل سنتيمتر مكعب، ما يجعله ألين من الجرانيت وأكثر عرضة للخدش بالأدوات المعدنية أو المنظفات الكاشطة. هذه الصلابة المتوسطة لا تُشكل عائقاً في الاستخدام المنزلي المعتاد لكنها تستدعي الابتعاد عن فرك السطح بإسفنجات خشنة أو محاليل حمضية. وكثافته المنخفضة نسبياً مقارنة بالجرانيت تجعل المغسلة أخف وزناً وأسهل في التثبيت.',
